from make_tile import *
ident=sys.argv[1];plan=read(P/'plan.json');p=next(x for x in plan['patches'] if x['id']==ident)
stem=ident+'.v2';assert not (P/'requests'/f'{stem}.request.json').exists()
prompt='''Use case: precise-object-edit. Edit image 1 ONLY, output one opaque square native 1254x1254 terrain crop with exactly the same stone boundaries, curved or straight joints, crop, scale and top-down oblique camera. This is a SURFACE MATERIAL CORRECTION, not a geometry change. Image 1 has unacceptable dense flake-like mottled marble texture and possibly an artificial horizontal material transition at y=1024 from a guide paste. Remove ALL that flake/mottle/crackle/marble/grain pattern everywhere, including dark gray surfaces. Render the entire image in one unified clean premium Q/chibi hand-painted stone finish: very smooth broad sparse tonal gradients, gently warm ivory, quiet stone faces, crisp but restrained rounded bevels, soft warm shadows. Follow the clean surface rendering of image 2, especially its quiet large slab faces. Follow image 3 approved designs painting finish ONLY, no UI/text/imported objects. Geometry must not shift; every existing major paving joint remains exactly in place. Keep existing gold strips but remove sparkly/mottled texture. Do not copy any straight rectangular guide paste boundary as a material break. No added stone divisions, cracks, noise, texture, speckles, flakes, veins, white frosting, plastic shine or blur. A stone slab must have one continuous consistent material across its full extent. Return only the image-1 crop, not the reference layout, no frame, no text.'''
refs=[p['native'],str(P/'references/q-style-only.png'),str(R/'designs/guild-ui-v2/source/guild-overview.png')]
promptfile=P/'prompts'/f'{stem}.prompt.txt';promptfile.write_text(prompt,encoding='utf-8');request=P/'requests'/f'{stem}.request.json'
write(request,{'prompt':prompt,'referenced_image_paths':refs})
p['previousNative']=p['native'];p['selectedStem']=stem;p['requestFile']=str(request);p['promptFile']=str(promptfile);p['submittedImages']=refs;p['status']='surface_retry_prepared';write(P/'plan.json',plan);print(json.dumps(read(request)))
